import Handlebars from 'handlebars';
import split from '../helper/string/split';

Handlebars.registerHelper('split', split);

describe('split helper', () => {

  // Тест для розбиття рядка за допомогою коми
  it('should split a string by a comma', () => {
    const template = Handlebars.compile('{{#each (split "a,b,c" ",")}}<span>{{this}}</span>{{/each}}');
    const result = template({});
    expect(result).toBe('<span>a</span><span>b</span><span>c</span>');
  });

  // Тест для розбиття рядка за допомогою пробілу
  it('should split a string by a space', () => {
    const template = Handlebars.compile('{{#each (split "Hello World Test" " ")}}<span>{{this}}</span>{{/each}}');
    const result = template({});
    expect(result).toBe('<span>Hello</span><span>World</span><span>Test</span>');
  });

  // Тест для розбиття числа
  it('should split a number converted to a string by a comma', () => {
    const template = Handlebars.compile('{{#each (split 12345 ",")}}<span>{{this}}</span>{{/each}}');
    const result = template({});
    expect(result).toBe('<span>12345</span>');
  });

  // Тест для розбиття рядка з використанням спеціальних символів
  it('should split a string by a special character (dash)', () => {
    const template = Handlebars.compile('{{#each (split "a-b-c" "-")}}<span>{{this}}</span>{{/each}}');
    const result = template({});
    expect(result).toBe('<span>a</span><span>b</span><span>c</span>');
  });

  // Тест для розбиття рядка з кількома символами роздільника
  it('should split a string using multiple characters as separator', () => {
    const template = Handlebars.compile('{{#each (split "one--two--three" "--")}}<span>{{this}}</span>{{/each}}');
    const result = template({});
    expect(result).toBe('<span>one</span><span>two</span><span>three</span>');
  });
});
